query StratzGetMatchFull ($id: Long!) {
	match(id: $id) {
		... MatchFullFields
	}
}
fragment MatchFullFields on MatchType {
	... MatchStandardFields
	fights {
		startTime
		endTime
		radiantKills
		direKills
		radiantNetworthDelta
		participants {
			steamAccountId
			heroId
			isRadiant
			kills
			deaths
		}
	}
	economy {
		time
		radiantNetworth
		direNetworth
		radiantExperience
		direExperience
	}
}
fragment MatchStandardFields on MatchType {
	... MatchSummaryFields
	players {
		... MatchPlayerFields
	}
	objectives {
		time
		type
		isRadiant
		steamAccountId
		heroId
		value
	}
	timeline {
		time
		type
		isRadiant
		steamAccountId
		heroId
		value
	}
}
fragment MatchSummaryFields on MatchType {
	id
	startDateTime
	durationSeconds
	didRadiantWin
	radiantKills
	direKills
	gameModeId
	lobbyTypeId
	regionId
	leagueId
	gameVersionId
	parsedDateTime
	statsDateTime
}
fragment MatchPlayerFields on MatchPlayerType {
	steamAccountId
	heroId
	isRadiant
	playerSlot
	kills
	deaths
	assists
	networth
	level
}

